from typing import List

def partition_yes(instance):
    numbers: List[int] = instance["numbers"]
    total = sum(numbers)
    if total % 2 == 1:
        return False
    target = total // 2
    # DP using set of reachable sums
    reachable = {0}
    for x in numbers:
        new = set()
        for s in reachable:
            ns = s + x
            if ns == target:
                return True
            if ns < target:
                new.add(ns)
        reachable.update(new)
    return target in reachable
EOF"}

